[CmdletBinding()]
param([string]$RepoRoot=(Get-Location).Path)
$ErrorActionPreference='Stop'
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path
if(!(Test-Path -LiteralPath (Join-Path $RepoRoot 'GuideVault.sln'))){throw 'Run from the GuideVault repository root.'}
function HashText([string]$s){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
$patch=@'
[{"path":"src/Guidevault.Web/wwwroot/app.js","before":"91410c66a6be7def0cfcf749d70ea9ba57b49924a368cc281199cc416a01099d","after":"b20249253df15dd3412efd49262f7a71315c1a53515dde718a4762629928e8c4","payload":""},{"path":"src/Guidevault.Web/wwwroot/index.html","before":"6da7a65dae9cf8f04d8775b26916fb8daad454884875f17f6340efc54bf1a205","after":"2cdd0ee5d169e4af8ffb2bce4379e339437f91e6b3da3d5f870f4ed95dd8df7f","payload":""}]
'@ | ConvertFrom-Json
$pending=@()
foreach($p in $patch){
    $path=Join-Path $RepoRoot $p.path
    $exists=Test-Path -LiteralPath $path -PathType Leaf
    $raw=if($exists){[IO.File]::ReadAllText($path).Replace("`r`n","`n")}else{''}
    $hash=HashText $raw
    $target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($p.payload))
    if((HashText $target) -ne $p.after){throw "Payload integrity check failed: $($p.path)"}
    if($exists -and $hash -eq $p.after){continue}
    if(($exists -and ($null -eq $p.before -or $hash -ne $p.before)) -or (!$exists -and $null -ne $p.before)){throw "Unexpected source revision: $($p.path). No files changed. Install on v8.0 Phase 4.6."}
    $pending+=@{name=$p.path;path=$path;target=$target;exists=$exists}
}
$programName='src/Guidevault.Web/Program.cs'
$programPath=Join-Path $RepoRoot $programName
$program=[IO.File]::ReadAllText($programPath).Replace("`r`n","`n")
$programTarget=$program
$anchor=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('ICAgIGNvbnRleHQuSXRlbXNbR3VpZGV2YXVsdFVzZXJDb250ZXh0S2V5XSA9IGF1dGhlbnRpY2F0ZWRVc2VyOw=='))
$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
if((HashText $anchor) -ne 'bf89b578dc969143f0781498c8d7046f9ab469f341ef7ad33cd294f2a92e6abc' -or (HashText $target) -ne '2f127836961473cffba36fb2f9a06336a3ec3e3694c0c61cfa8479306dd42426'){throw 'API payload integrity check failed.'}
if(!$programTarget.Contains($target)){
    if(([regex]::Matches($programTarget,[regex]::Escape($anchor))).Count -ne 1){throw 'Unexpected Phase 4.6 Program.cs layout. No files changed.'}
    $programTarget=$programTarget.Replace($anchor,$target)
}
$anchor=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('ICAgICAgICBpZiAoc2hlbHZlcy5Db3VudCA9PSAwKSBzaGVsdmVzLkFkZCgicmVjZW50bHktYWRkZWQiKTs='))
$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('ICAgICAgICAvLyBBbiBleHBsaWNpdGx5IGVtcHR5IHNoZWxmIGxpc3QgaXMgYSB2YWxpZCBsYXlvdXQuIFRoZSBtb2RlbCBzdXBwbGllcyB0aGUgZGVmYXVsdCBmb3IgbmV3IHNldHRpbmdzLg=='))
if((HashText $anchor) -ne 'cb25f6bef71461ba9868124fcd41536fac5ddd81273a06eaadf88a531ee32c41' -or (HashText $target) -ne 'e50f63f171a0ee491d50981f3008bbc2dc3dd14bd078696c10d8be96ba1ab7ec'){throw 'API payload integrity check failed.'}
if(!$programTarget.Contains($target)){
    if(([regex]::Matches($programTarget,[regex]::Escape($anchor))).Count -ne 1){throw 'Unexpected Phase 4.6 Program.cs layout. No files changed.'}
    $programTarget=$programTarget.Replace($anchor,$target)
}
$anchor=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('YXBwLk1hcEdldCgiL2FwaS9zZXJ2ZXIvYmFja3VwcyIsICgpID0+IFJlc3VsdHMuT2soc2VydmVyU2V0dGluZ3NTdG9yZS5MaXN0TGlicmFyeUJhY2t1cHMoKSkpOw=='))
$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
if((HashText $anchor) -ne 'da819a9e7a093d89c93a8991cd7d53e864e18cdf4e14dd28f92563419831cb23' -or (HashText $target) -ne '268866087c961a16d034324a5da40caf36b7bfdb0fffd8251fd02802b044cdb8'){throw 'API payload integrity check failed.'}
if(!$programTarget.Contains($target)){
    if(([regex]::Matches($programTarget,[regex]::Escape($anchor))).Count -ne 1){throw 'Unexpected Phase 4.6 Program.cs layout. No files changed.'}
    $programTarget=$programTarget.Replace($anchor,$target)
}
$anchor=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('ICAgICAgICAgICAgICAgIC5UYWtlKDUwKQogICAgICAgICAgICAgICAgLlNlbGVjdChpbmZvID0+IG5ldyBHdWlkZXZhdWx0QmFja3VwRmlsZUluZm8='))
$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('ICAgICAgICAgICAgICAgIC5TZWxlY3QoaW5mbyA9PiBuZXcgR3VpZGV2YXVsdEJhY2t1cEZpbGVJbmZv'))
if((HashText $anchor) -ne '212e0d78320bf4249053c0371293ce69f5578981760d755997a9b803d7544d77' -or (HashText $target) -ne '25bc97d2152ac8a8c3fc1213ac5fe14505bf441c3586989a3c646340a0f5ad41'){throw 'API payload integrity check failed.'}
if(!$programTarget.Contains($target)){
    if(([regex]::Matches($programTarget,[regex]::Escape($anchor))).Count -ne 1){throw 'Unexpected Phase 4.6 Program.cs layout. No files changed.'}
    $programTarget=$programTarget.Replace($anchor,$target)
}
$anchor=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('ICAgIHB1YmxpYyBHdWlkZXZhdWx0QmFja3VwUHJldmlldyBQcmV2aWV3TGlicmFyeUJhY2t1cChzdHJpbmcgZmlsZU5hbWUp'))
$target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
if((HashText $anchor) -ne 'd7c5e78e3a4db70c728d5841d1ea3c249f5b8bd5489747fdff1a049955a399b8' -or (HashText $target) -ne '546d89d5195238056c4e93d3c0291f9726539a7cce42f375d47e741cc259280d'){throw 'API payload integrity check failed.'}
if(!$programTarget.Contains($target)){
    if(([regex]::Matches($programTarget,[regex]::Escape($anchor))).Count -ne 1){throw 'Unexpected Phase 4.6 Program.cs layout. No files changed.'}
    $programTarget=$programTarget.Replace($anchor,$target)
}
if($programTarget -cne $program){$pending+=@{name=$programName;path=$programPath;target=$programTarget;exists=$true}}
$paths=@($patch | ForEach-Object {$_.path})+@($programName)
$backup=Join-Path $RepoRoot ('.guidevault-patch-backups/library-ui-cleanup-v1-'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
foreach($p in $pending){if($p.exists){$dest=Join-Path $backup $p.name;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest)|Out-Null;Copy-Item -LiteralPath $p.path -Destination $dest}}
try{
    foreach($p in $pending){
        $bom=$false
        if($p.exists){$bytes=[IO.File]::ReadAllBytes($p.path);$bom=$bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191}
        [IO.File]::WriteAllText($p.path,$p.target,[Text.UTF8Encoding]::new($bom))
        if([IO.File]::ReadAllText($p.path) -cne $p.target){throw "Write verification failed: $($p.name)"}
    }
}catch{foreach($p in $pending){if($p.exists){Copy-Item -LiteralPath (Join-Path $backup $p.name) -Destination $p.path -Force}else{Remove-Item -LiteralPath $p.path -ErrorAction SilentlyContinue}};throw}
foreach($path in $paths){
    $tracked=& git -C $RepoRoot ls-files -- $path
    if($LASTEXITCODE -ne 0){throw "Git ls-files failed: $path"}
    if($tracked){
        & git -C $RepoRoot update-index --no-assume-unchanged -- $path
        if($LASTEXITCODE -ne 0){throw "Could not clear assume-unchanged: $path"}
        & git -C $RepoRoot update-index --no-skip-worktree -- $path
        if($LASTEXITCODE -ne 0){throw "Could not clear skip-worktree: $path"}
    }
    & git -C $RepoRoot add -f -- $path
    if($LASTEXITCODE -ne 0){throw "Git staging failed: $path"}
    & git -C $RepoRoot diff --exit-code -- $path
    if($LASTEXITCODE -ne 0){throw "Working tree differs from staged source: $path"}
}
Write-Host "Backup (if changes made): $backup"
Write-Host 'GuideVault Library UI Cleanup v1 installed and staged. Magazine scanner and existing data unchanged.' -ForegroundColor Green
& git -C $RepoRoot diff --cached --stat
